import { CommonModule } from '@angular/common';
import { Component, HostListener, OnInit, OnDestroy, inject } from '@angular/core';
import { MatTooltipModule } from '@angular/material/tooltip';
import { ActivatedRoute } from '@angular/router';
import { MyfilesModule } from '../../../modules/myfiles/myfiles.module';
import { HeaderService } from '../../../../core/services/header/header.service';
import { FileexplorerComponent } from '../../../../shared/components/myfiles/fileexplorer/fileexplorer.component';
import { ButtonComponent } from '../../../../shared/components/button/button.component';
import { IconComponent } from '../../../../shared/components/icon/icon.component';
import { SectionRes } from '../../../../adminpanel/interfaces/bundlemanage.interface';
import { Subscription } from 'rxjs';
import { SocketService } from '../../../../core/services/socket/socket.service';
import { exportSocketRes } from '../../../interfaces/export.interface';
import { CommonfunctionService } from '../../../../core/utility/commonfunction.service';
import { Title } from '@angular/platform-browser';
import { CanComponentDeactivate } from '../../../../shared/guards/confirm-exit.guard';
import { BroadcastingService } from '../../../../core/services/broadcasting/broadcasting.service';
import { BROADCAST_EVENTS, MYFILES_CS_EVENTS } from '../../../utility/user-panel-constants';
import { CommunicationService } from '../../../../shared/services/communication/communication.service';
import { UserPermissionService } from '../../../../shared/services/user-permission/user-permission.service';
import { NotificationsService } from '../../../../shared/services/notifications.service';

@Component({
  selector: 'app-filesaction',
  standalone: true,
  imports: [CommonModule, MyfilesModule, FileexplorerComponent, ButtonComponent, IconComponent, MatTooltipModule,

  ],
  templateUrl: './filesaction.component.html',
  styleUrl: './filesaction.component.scss'
})
export class FilesactionComponent implements CanComponentDeactivate, OnInit, OnDestroy {
  private readonly titleS = inject(Title);
  activeSection: SectionRes;
  nCaseid: string;
  nSectionid: string;
  isExport: boolean = false;
  exportData: any;
  socketSubscription: Subscription;
  notifSubscription: Subscription;
  nUPid: string;

  private __origFav: string | null = null;
  private __origTitle: string | null = null;

  @HostListener('window:beforeunload', ['$event'])
  unloadNotification($event: any): any {
    if (this.hs.isGlobalSearch) {
      const confirmationMessage = 'Tip: Closing the tab will remove your current search results.';
      $event.returnValue = confirmationMessage;
      if (confirmationMessage) {
        this.broadCastService.portMessage({
          event: BROADCAST_EVENTS.DEACTIVATE_SEARCH, data: { nCaseid: this.hs.nCaseid || this.hs?.Casedetail?.nCaseid, cWithin: this.hs.search_within }
        })
      }
      return confirmationMessage;
    }
  }
  constructor(public hs: HeaderService, private readonly route: ActivatedRoute, private readonly ss: SocketService, private readonly cf: CommonfunctionService,
    private readonly broadCastService: BroadcastingService, private readonly cs: CommunicationService, private readonly userPermissions: UserPermissionService,
    private readonly notifications: NotificationsService
  ) {
    const params = this.route.snapshot.params;
    const parsedParams = JSON.parse(atob(params["id"]));
    this.nCaseid = parsedParams?.id ?? 0;
    this.nUPid = parsedParams?.nUPid ?? 0;
    this.hs.nCaseid = this.nCaseid;
    try {
      this.hs.jFilter = parsedParams?.jFilter ?? this.hs.jFilter;
      if (this.hs.jFilter?.isGlobalSearch) {
        this.hs.isGlobalSearch = true;
        this.hs.search_within = this.hs.jFilter.cWithin;
      }
    } catch (error) {
      console.error('Error parsing filter:', error);
    }
    this.socketSubscription = this.ss.getFileExports().subscribe((res: any) => {
      console.log('export', res);
      const data: exportSocketRes = res?.data?.data || [];
      if (data && data.nCaseid == this.nCaseid) {

        console.log('export data', data);

        if (data.cStatus == 'P' || data.cStatus == 'F') {
          this.exportData = data;
          this.isExport = true;
        } else if (data.cStatus == 'C') {
          this.exportData = data;
          setTimeout(() => {
            this.isExport = false;
          }, 10000);
        }
      }
    })

    // Listen for real-time user notifications and badge favicon if backgrounded
    this.notifSubscription = this.ss.getUserNotifications().subscribe((res: any) => {
      try {
        if (res?.nCaseid && this.nCaseid == res?.nCaseid) {
          this.notifications._isNotification.next(true);
          if (!document.hasFocus()) {
            this.enableAttention();
          }
        }
      } catch { }
    });
  }

  ngOnInit(): void {
    this.userPermissions.userPermissionList(this.nCaseid);
    if (this.hs.isGlobalSearch) {
      if (this.hs.search_within === 'I') {
        this.titleS.setTitle('Content Search');
      } else {
        this.titleS.setTitle('Metadata Search');
      }
    } else {
      this.titleS.setTitle('HearingHub');
    }
    setTimeout(() => {
      this.hs.updatePath('my files');
      this.hs.updateisCase(true);
    }, 10);

    // Prefetch notifications for this case and, if there are unseen ones and the tab isn't focused, show attention
    this.notifications.getNotifcationList(this.nCaseid).then(() => {
      if (this.notifications._isNotification.value) {
        this.enableAttention();
      }
    }).catch(() => { /* ignore */ });

    this.notifications.isNotification$
      .subscribe(isNotif => {
        if (isNotif) {
          this.enableAttention();
        } else {
          this.disableAttention();
        }
      });
  }

  ngOnDestroy(): void {
    try {
      this.socketSubscription?.unsubscribe();
    } catch (error) {
      console.error('Error unsubscribing from socket:', error);
    }
    try {
      this.notifSubscription?.unsubscribe();
    } catch (error) {
      console.error('Error unsubscribing from notifications:', error);
    }
  }

  changeSection(x: SectionRes): void {
    this.activeSection = x;
    this.nSectionid = this.activeSection.nSectionid;
  }


  calcCompPprogres(completedFiles: number, totalFiles: number): string {
    if (totalFiles === 0) {
      return '0'; // To avoid division by zero
    }
    return (((completedFiles || 0) / (totalFiles || 0)) * 100).toFixed();
  }

  openExport() {
    this.cf.goto('myfiles/export', { id: this.nCaseid });
  }

  canDeactivate(): boolean {
    if (this.hs.isGlobalSearch && this.hs.jFilter?.cSearch) {
      const userConfirmed = confirm('Tip: Closing the tab will remove your current search results.');
      if (!userConfirmed) {
        return false;
      }
    }
    this.broadCastService.portMessage({
      event: BROADCAST_EVENTS.DEACTIVATE_SEARCH, data: { nCaseid: this.hs.nCaseid || this.hs?.Casedetail?.nCaseid, cWithin: this.hs.search_within }
    })
    this.cs.callFunction({ event: MYFILES_CS_EVENTS.CLEAR_SEARCH_ALL });
    return true;
  }

  @HostListener('window:blur')
  onWindowBlur(): void {
    // small delay to ensure the tab actually backgrounded
    setTimeout(() => {
      if (!document.hasFocus() && this.notifications._isNotification.value) {
        this.enableAttention();
      }
    }, 150);
  }

  @HostListener('window:focus')
  onWindowFocus(): void {
    if (this.notifications._isNotification.value) {
      this.enableAttention();
    }
  }

  private async setFavicon(href: string): Promise<void> {
    document.querySelectorAll('link[rel~="icon"]').forEach(n => n.remove());
    const link = document.createElement('link');
    link.rel = 'icon';
    link.href = href;
    document.head.appendChild(link);
  }

  private async makeBadgedFavicon(srcHref: string): Promise<string> {
    const img = new Image();
    img.crossOrigin = 'anonymous';
    img.src = srcHref;
    await new Promise(r => { img.onload = r; (img as any).onerror = r; });

    const size = 32, pad = 2, r = 7, cx = size - r - pad + 2, cy = r + pad - 2;
    const c = document.createElement('canvas');
    c.width = c.height = size;
    const ctx = c.getContext('2d');
    if (!ctx) return srcHref;

    // draw the base image slightly inset to visually shrink it a bit
    const inset = 2; // px
    if (img.width) ctx.drawImage(img, inset, inset, size - inset * 2, size - inset * 2);
    else { ctx.fillStyle = '#fff'; ctx.fillRect(0, 0, size, size); }

    ctx.beginPath(); ctx.arc(cx, cy, r, 0, Math.PI * 2); ctx.fillStyle = '#d11'; ctx.fill();
    // white border around the red dot
    ctx.lineWidth = 2;
    ctx.strokeStyle = '#fff';
    ctx.stroke();
    return c.toDataURL('image/png');
  }

  private async enableAttention(): Promise<void> {
    const link = document.querySelector('link[rel~="icon"]') || (() => {
      const l = document.createElement('link'); l.rel = 'icon'; (l as any).href = '/favicon.ico'; document.head.appendChild(l); return l;
    })();
    const currentHref = (link as HTMLLinkElement).href;
    if (!this.__origFav) this.__origFav = currentHref;
    this.__origTitle ??= document.title;

    const badged = await this.makeBadgedFavicon(this.__origFav);
    await this.setFavicon(badged);
  }

  private async disableAttention(): Promise<void> {
    if (this.__origFav) await this.setFavicon(this.__origFav);
    if (this.__origTitle != null) document.title = this.__origTitle;
  }
}
